// 프로그램 연동 시트 → 주간 발행 보고
const 목표건수 = 100; // ← 캠페인 목표 총량에 맞게 수정
const rows = items.map(i => i.json).filter(r => (r['제목'] || '').toString().trim());

// 발행일 파싱: "26.07.18" (YY.MM.DD)
const parse = (s) => {
  s = (s || '').toString().trim();
  const m = s.match(/(\d{2})[.\-/](\d{1,2})[.\-/](\d{1,2})/);
  if (!m) return null;
  const d = new Date(2000 + (+m[1]), (+m[2]) - 1, (+m[3]));
  return isNaN(d) ? null : d;
};
const done = (s) => /발행완료|완료/.test((s || '').toString());

const now = new Date();
const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
let total = 0, week = 0, pending = 0, rejected = 0;
const weekByClient = {}, totalByClient = {};
for (const r of rows) {
  const status = r['발행상태'] || '';
  const confirm = r['컨펌'] || '';
  const client = r['업체'] || '기타';
  if (done(status)) {
    total++;
    totalByClient[client] = (totalByClient[client] || 0) + 1;
    const d = parse(r['발행일']);
    if (d && d >= weekAgo && d <= now) {
      week++;
      weekByClient[client] = (weekByClient[client] || 0) + 1;
    }
  } else if (/반려/.test(confirm)) {
    rejected++;
  } else if (!confirm.toString().trim()) {
    pending++;
  }
}
const kst = new Date(now.getTime() + 9 * 60 * 60 * 1000);
const pad = (n) => String(n).padStart(2, '0');
const ymd = `${String(kst.getUTCFullYear()).slice(2)}.${pad(kst.getUTCMonth() + 1)}.${pad(kst.getUTCDate())}`;
const wk = Object.entries(weekByClient).sort((a, b) => b[1] - a[1])
  .map(([c, n]) => `  · ${c}: ${n}개`).join('\n') || '  · (최근 7일 발행 없음)';
const tot = Object.entries(totalByClient).sort((a, b) => b[1] - a[1])
  .map(([c, n]) => `  · ${c}: ${n}개`).join('\n');

let msg = `안녕하세요. 작업 중간 보고 드립니다.\n`;
msg += `소식글 발행 ${total}/${목표건수}\n`;
msg += `${ymd} 기준 / 최근 7일 ${week}개 완료\n\n`;
msg += `[고객사별 최근 7일]\n${wk}\n\n`;
msg += `[고객사별 누적]\n${tot}`;
if (pending > 0) msg += `\n\n⏳ 검수 대기: ${pending}건`;
if (rejected > 0) msg += `\n🚫 반려: ${rejected}건`;

return [{ json: { message: msg, total, week, pending, rejected } }];
